void Handle(Message message)
{
    ArgumentNullException.ThrowIfNull(message);
    ArgumentException.ThrowIfNullOrWhiteSpace(message.Body);

    string body = message.Body;
    string? correlation = message.MessageAttributes.TryGetValue("correlationId", out var attr)
        ? attr.StringValue
        : null;
    string key = correlation ?? message.MessageId;
}

int? TryGetRetryCount(Message msg)
